import React from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createStackNavigator } from '@react-navigation/stack';

// Import all the screens
import HomeScreen from './screens/HomeScreen';
import NewReportScreen from './screens/NewReportScreen';
import ReportDetailsScreen from './screens/ReportDetailsScreen';
import LoginScreen from './screens/LoginScreen';
import RegisterScreen from './screens/RegisterScreen';
import ProfileScreen from './screens/ProfileScreen';

const Stack = createStackNavigator();

export default function App() {
  return (
    <NavigationContainer>
      <Stack.Navigator initialRouteName="Login">
        <Stack.Screen name="Login" component={LoginScreen} options={{ title: 'Login' }} />
        <Stack.Screen name="Register" component={RegisterScreen} options={{ title: 'Create Account' }} />
        <Stack.Screen name="Home" component={HomeScreen} options={{ title: 'Civic Issue Reports' }} />
        <Stack.Screen name="NewReport" component={NewReportScreen} options={{ title: 'Submit New Report' }} />
        <Stack.Screen name="ReportDetails" component={ReportDetailsScreen} options={{ title: 'Report Details' }} />
        <Stack.Screen name="Profile" component={ProfileScreen} options={{ title: 'Your Profile' }} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
